  it "refuses an audit whose associated company differs from its entry's company instead of filing it under either" do
    entries_by_id = { 41 => { "id" => 41, "company_id" => 5, "created_at" => Time.utc(2025, 3, 1) } }
    audits = [
      { id: 601, action: "update", associated_type: "Company", associated_id: 6, auditable_id: 41,
        user_type: "User", user_id: 11, username: nil,
        audited_changes: { "note" => ["a", "b"] }, created_at: Time.utc(2025, 3, 2) }
    ]

    result = described_class.convert(audits:, entries_by_id:)

    expect(result[:rows]).to eq([])
    expect(result[:refusals].fetch(5)).not_to be_empty
    expect(result[:refusals].fetch(5).join("\n")).to include("601")
  end
end
